import logging
import math

from taf.internal.gnb.oam.coam.vdu.client.fm.v1 import (
    ApiClient,
    Configuration,
    FmApi,
    ApiException
)

from taf.gnb.oam.coam.vdu.services.fm.http_client_v1 import FMv1HttpClient
from taf.gnb.oam.coam.vdu.services.sec.sec_licensed_v1 import SECLicensedv1
from taf.gnb.oam.coam.vdu.services.sec.sec_v1 import SECv1
from taf.gnb.oam.coam.vdu.utilities.logger import log_request_response
from taf.gnb.oam.coam.vdu.utilities.token_provider import auto_token_refresh
from taf.gnb.oam.coam.vdu.utilities.token_storage import TokenStorage


@auto_token_refresh(api_exception=ApiException)
class FMv1:
    def __init__(self, con_details):
        self.con_details = con_details
        self.token_storage = TokenStorage(connection_name=con_details.alias)
        self.sec = SECLicensedv1.get_instance(connection_name=con_details.alias) \
            if con_details.use_m2m else SECv1.get_instance(connection_name=con_details.alias)

        conf = Configuration()
        conf.verify_ssl = False
        conf.host = con_details.get_api_client_configuration(original_endpoint=conf.host)
        self.configuration = conf

        api_client = ApiClient(configuration=conf)
        api_client.request = log_request_response(api_client.request)

        self.fm_api = FmApi(api_client)
        self.local_client = FMv1HttpClient(base_url=con_details.base_url,
                                           connection_alias=con_details.alias)

    def vdu_get_active_alarm(self, timeout=30, paging=True, **kwargs):
        if paging:
            return self.fm_api.get_active_alarms(_request_timeout=timeout, **kwargs)
        else:
            alarms_object = self.fm_api.get_active_alarms(page_number=1, items_per_page=10,
                                                          _request_timeout=timeout, **kwargs)
            total = alarms_object.total
            logging.info(f'There are total {total} alarms')
            if total > 10:
                for page_number in range(2, int(math.ceil(float(total) / 10)) + 1):
                    alarms = self.fm_api.get_active_alarms(page_number=page_number, items_per_page=10,
                                                           _request_timeout=timeout, **kwargs).alarms
                    alarms_object.alarms.extend(alarms)
            return alarms_object

    def vdu_get_historical_alarms(self, timeout=None, paging=True, page_number=None, items_per_page=None, **kwargs):
        if paging:
            return self.local_client.get_historical_alarms(timeout=timeout, **kwargs)
        else:
            if page_number and items_per_page:
                return self.local_client.get_historical_alarms(page_number=page_number, items_per_page=items_per_page,
                                                               timeout=timeout, **kwargs)
            else:
                raise ValueError('page_number and items_per_page must be provided when paging is set to False.')

    def vdu_get_active_alarms_summary(self, timeout=None):
        return self.fm_api.get_active_alarms_summary(_request_timeout=timeout)

    def vdu_get_historical_alarms_summary(self, timeout=None):
        return self.fm_api.get_historical_alarms_summary(_request_timeout=timeout)
